  r.patient.age = 90.5;
  expectError(r, 422, "INVALID_VALUE", "/patient/age");
  r = baseRequest();
  r.patient.sex = "M";
  expectError(r, 422, "INVALID_VALUE", "/patient/sex");
  r = baseRequest();
  r.target.site = "Effect";
  expectError(r, 422, "INVALID_VALUE", "/target/site");
  r = baseRequest();
  r.target.value = -1;
  expectError(r, 422, "INVALID_VALUE", "/target/value");
  r = baseRequest();
  r.pump.maxRate = 0;
  expectError(r, 422, "INVALID_VALUE", "/pump/maxRate");
  r = baseRequest();
  r.pump.maxRate = 1e5 + 1;
  expectError(r, 422, "INVALID_VALUE", "/pump/maxRate");
  r = baseRequest();
  r.pump.minRate = 1200;
  expectError(r, 422, "INVALID_VALUE", "/pump/minRate");
  r = baseRequest();
  r.pump.rateResolution = 121;
  expectError(r, 422, "INVALID_VALUE", "/pump/rateResolution");
  r = baseRequest();
  r.pump.rateResolution = 0;
  expectError(r, 422, "INVALID_VALUE", "/pump/rateResolution");
  r = baseRequest();
  r.pump.currentRate = -1;
  expectError(r, 422, "INVALID_VALUE", "/pump/currentRate");
  r = baseRequest();
  r.pump.state = "Running";
  expectError(r, 422, "INVALID_VALUE", "/pump/state");
  r = baseRequest();
  r.pump.volumeInfused = { value: -1, units: "mL" };
  expectError(r, 422, "INVALID_VALUE", "/pump/volumeInfused/value");
  r = baseRequest();
  r.timing.interval = 0.5;
  expectError(r, 422, "INVALID_VALUE", "/timing/interval");
  r = baseRequest();
  r.timing.interval = 61;
  expectError(r, 422, "INVALID_VALUE", "/timing/interval");
  r = baseRequest();
  r.timing.latency = -1;
  expectError(r, 422, "INVALID_VALUE", "/timing/latency");
  r = baseRequest();
  r.lookAhead = { concentration: 0 };
  expectError(r, 422, "INVALID_VALUE", "/lookAhead/concentration");
  r = baseRequest();
  r.infusate.concentration = 1e-305;
  expectError(r, 422, "INVALID_VALUE", "/infusate/concentration");
  r = baseRequest();
  r.history = [{ time: "2026-10-11T13:59:00Z", infusate: { concentration: 0.0001, units: "mg/mL" } }];
  expectError(r, 422, "INVALID_VALUE", "/history/0/infusate/concentration");
  r = baseRequest();
  r.requestId = "caf\u00e9";
  expectError(r, 422, "INVALID_VALUE", "/requestId");
  r = baseRequest();
  r.requestId = "x".repeat(129);
  expectError(r, 422, "INVALID_VALUE", "/requestId");
  // 1e400 parses to Infinity, which is a finite-value failure, not a type failure.
  r = JSON.parse(JSON.stringify(baseRequest()).replace('"maxRate":1200', '"maxRate":1e400'));
  assert.equal(r.pump.maxRate, Infinity);
  expectError(r, 422, "INVALID_VALUE", "/pump/maxRate");
  r = baseRequest();
  r.history = [{ time: "2026-10-11T13:59:00Z", rate: Infinity, units: "mL/hr" }];
  expectError(r, 422, "INVALID_VALUE", "/history/0/rate");
  r = baseRequest();
  r.history = [{ time: "2026-10-11T13:59:00Z", rate: -1, units: "mL/hr" }];
