test("HISTORY_INVALID: the kind keys and the fields of a kind", () => {
  let r = baseRequest();
  r.history = [{ time: "2026-10-11T13:59:00Z" }];
  expectError(r, 422, "HISTORY_INVALID", "/history/0");
  r = baseRequest();
  r.history = [{}];
  expectError(r, 422, "HISTORY_INVALID", "/history/0");
  r = baseRequest();
  r.history = [{ time: "2026-10-11T13:59:00Z", rate: 1, bolus: 2, units: "mg" }];
  expectError(r, 422, "HISTORY_INVALID", "/history/0");
  r = baseRequest();
  r.history = [{ time: "2026-10-11T13:59:00Z", rate: null, bolus: 2, units: "mg" }]; // null is absent: a bolus
  const response = tciNextRate(r, receivedAtFor(r));
  assert.ok(response.state.now.cp > 0);
  r = baseRequest();
  r.history = [{ time: "2026-10-11T13:59:00Z", bolus: 2, units: "mg", delivered: null, from: "2026-10-11T13:59:00Z" }];
  expectError(r, 422, "HISTORY_INVALID", "/history/0/from");
  r = baseRequest();
  r.history = [{ time: "2026-10-11T13:59:00Z", infusate: { concentration: 10, units: "mg/mL" }, units: "mg" }];
  expectError(r, 422, "HISTORY_INVALID", "/history/0/units");
  r = baseRequest();
  r.history = [
    { time: "2026-10-11T13:59:00Z", infusate: { concentration: 10, units: "mg/mL" } },
    { time: "2026-10-11T13:59:00Z", infusate: { concentration: 10, units: "mg/mL" } },
  ];
  expectError(r, 422, "HISTORY_INVALID", "/history/1");
  // Two boluses at one instant are summed, not refused.
  r = baseRequest();
  r.history = [
    { time: "2026-10-11T13:59:30Z", bolus: 10, units: "mg" },
    { time: "2026-10-11T13:59:30Z", bolus: 10, units: "mg" },
  ];
  const two = tciNextRate(r, receivedAtFor(r));
  r.history = [{ time: "2026-10-11T13:59:30Z", bolus: 20, units: "mg" }];
  const one = tciNextRate(r, receivedAtFor(r));
  assert.ok(relativeError(two.state.now.ce, one.state.now.ce) < 1e-12);
});

test("HISTORY_OVERLAP, HISTORY_IN_FUTURE and the HISTORY_CLOCK_SKEW clamp", () => {
  let r = baseRequest();
  r.history = [
    { from: "2026-10-11T13:50:00Z", to: "2026-10-11T13:55:00Z", delivered: 1, units: "mL" },
    { from: "2026-10-11T13:54:59Z", to: "2026-10-11T13:58:00Z", delivered: 1, units: "mL" },
  ];
  expectError(r, 422, "HISTORY_OVERLAP", "/history/1");
  r = baseRequest();
  r.history = [{ from: "2026-10-11T13:50:00Z", to: "2026-10-11T14:00:02.001Z", delivered: 1, units: "mL" }];
  expectError(r, 422, "HISTORY_IN_FUTURE", "/history/0/to");
  r = baseRequest();
  r.history = [
    { time: "2026-10-11T13:59:00Z", rate: 100, units: "mL/hr" },
    { time: "2026-10-11T14:00:01.000Z", rate: 0, units: "mL/hr" },
  ];
  const response = tciNextRate(r, receivedAtFor(r));
  assert.deepEqual(response.warnings.map((w) => w.code), ["HISTORY_CLOCK_SKEW"]);
  assert.equal(response.warnings[0].pointer, "/history/1/time");
  // Clamped to now: the pump ran 100 mL/hr for the whole minute and is now at 0.
  const minute = tciNextRate({ ...r, history: [r.history[0]] }, receivedAtFor(r));
  assert.ok(relativeError(response.delivered.fromHistory, minute.delivered.fromHistory) < 1e-12);
  // 1 min at 100 mL/hr of 10 mg/mL, in mg
  assert.ok(relativeError(response.delivered.fromHistory, 100 * 10 / 60) < 1e-12, response.delivered.fromHistory);
});

