test("PUMP_NOT_RUNNING, RATE_MISMATCH, DELIVERY_MISMATCH, SYRINGE_LOW and CLOCK_SKEW", () => {
  const history = [
    { time: "2026-10-11T13:58:00Z", rate: 600, units: "mL/hr" },
    { time: "2026-10-11T13:58:10Z", rate: 60, units: "mL/hr" },
  ];
  let r = baseRequest();
  r.history = history;
  r.pump.state = "occlusion";
  r.pump.currentRate = 999; // not raised while the pump is not running
  let response = tciNextRate(r, receivedAtFor(r));
  assert.deepEqual(response.warnings.map((w) => w.code), ["PUMP_NOT_RUNNING"]);
  assert.equal(response.state.effectiveAt.cp, tciNextRate({ ...r, pump: { ...r.pump, state: "paused" } }, receivedAtFor(r)).state.effectiveAt.cp);
  r = baseRequest();
  r.history = history;
  r.pump.currentRate = 60.05; // within rateResolution: no warning
  assert.deepEqual(tciNextRate(r, receivedAtFor(r)).warnings, []);
  r.pump.currentRate = 61;
  response = tciNextRate(r, receivedAtFor(r));
  assert.deepEqual(response.warnings.map((w) => [w.code, w.pointer]), [["RATE_MISMATCH", "/pump/currentRate"]]);
  r = baseRequest();
  r.history = history;
  const delivered = 600 / 60 * (10 / 60) * 10 + 60 / 60 * (110 / 60) * 10; // mg
  r.pump.volumeInfused = { value: delivered * 1.01, units: "mg" };
  response = tciNextRate(r, receivedAtFor(r));
  assert.deepEqual(response.warnings, []);
  assert.ok(relativeError(response.delivered.reported, delivered * 1.01) < 1e-12);
  r.pump.volumeInfused = { value: delivered / 10 + 0.6, units: "mL" }; // 0.6 mL over: beyond 0.5 mL and 2%
  response = tciNextRate(r, receivedAtFor(r));
  assert.deepEqual(response.warnings.map((w) => w.code), ["DELIVERY_MISMATCH"]);
  r = baseRequest();
  r.history = history;
  r.pump.syringeVolumeRemaining = { value: 0.05, units: "mL" };
  response = tciNextRate(r, receivedAtFor(r));
  assert.deepEqual(response.warnings.map((w) => w.code), ["SYRINGE_LOW"]);
  assert.match(response.prediction.syringeEmptyAt, /Z$/);
  r = baseRequest();
  response = tciNextRate(r, new Date("2026-10-11T14:01:00.000Z"));
  assert.deepEqual(response.warnings.map((w) => [w.code, w.pointer]), [["CLOCK_SKEW", "/now"]]);
  assert.deepEqual(tciNextRate(r, new Date("2026-10-11T14:00:29.000Z")).warnings, []);
});

test("syringeEmptyAt: null with the pump off, the latency's own emptying, and absent without the field", () => {
  let r = baseRequest();
  r.target.value = 0;
  r.pump.syringeVolumeRemaining = { value: 10, units: "mL" };
  let response = tciNextRate(r, receivedAtFor(r));
  assert.equal(response.prediction.syringeEmptyAt, null);
  assert.ok(Object.prototype.hasOwnProperty.call(response.prediction, "syringeEmptyAt"));
  r = baseRequest();
  r.history = [{ time: "2026-10-11T13:59:00Z", rate: 1200, units: "mL/hr" }];
  r.pump.syringeVolumeRemaining = { value: 0.1, units: "mL" }; // 1200 mL/hr empties 0.1 mL in 0.3 s
  response = tciNextRate(r, receivedAtFor(r));
  assert.equal(response.prediction.syringeEmptyAt, "2026-10-11T14:00:00.300Z");
  r = baseRequest();
  response = tciNextRate(r, receivedAtFor(r));
  assert.ok(!("syringeEmptyAt" in response.prediction));
  assert.ok(!("lookAhead" in response.prediction));
});

test("lookAhead: zero when already below, null beyond the horizon", () => {
  let r = baseRequest();
  r.lookAhead = { concentration: 1 };
  let response = tciNextRate(r, receivedAtFor(r)); // empty body: already below
  assert.deepEqual(response.prediction.lookAhead, {
    site: "effect", concentration: 1, units: "mcg/mL", decrementSeconds: 0, horizonSeconds: 30000, beyondHorizon: false,
  });
  const c = rateCases.cases.find((x) => x.name === "c_maintenance_20min_propofol");
  r = { ...c.request, lookAhead: { concentration: 1e-9 } };
  response = tciNextRate(r, receivedAtFor(r));
  assert.equal(response.prediction.lookAhead.decrementSeconds, null);
  assert.equal(response.prediction.lookAhead.beyondHorizon, true);
});

// ---------------------------------------------------------------------------
// The computation, checked independently of the fixtures

test("the superposition equals the step-by-step recurrence (test group 1 of the R suite)", () => {
  for (const name of ["c_maintenance_20min_propofol", "c_maintenance_20min_remifentanil", "f_hand_bolus_30s_ago_propofol"]) {
    const c = rateCases.cases.find((x) => x.name === name);
    const response = tciNextRate(c.request, receivedAtFor(c.request));
    const p = c.request.patient;
    const model = resolveModel({ drug: c.drug, ...p });
    // The syringe is 10 mg/mL or 50 mcg/mL: already in base units per mL.
    const concBase = c.request.infusate.concentration;
    // Minutes relative to now, as the port works (absolute epoch minutes
    // would lose 4e-9 min per step to double precision).
    const nowMs = Date.parse(c.request.now);
    const events = c.request.history
      .map((h) => ({ ...h, t: (Date.parse(h.time) - nowMs) / 1000 / 60 }))
      .sort((a, b) => a.t - b.t);
    let state = emptyState();
    let rate = 0;
    let t = events[0].t;
    for (const ev of events) {
      state = advance(state, ev.t - t, rate, model);
      t = ev.t;
      if (ev.rate !== undefined) rate = ev.rate * concBase / 60;
      if (ev.bolus !== undefined) {
        state = { p: state.p.map((v, i) => v + model.coef.pbolus[i] * ev.bolus), e: state.e.map((v, i) => v + model.coef.ebolus[i] * ev.bolus) };
      }
    }
    state = advance(state, 0 - t, rate, model);
    assert.ok(relativeError(cp(state), response.state.now.cp) < 1e-12, `${name} cp ${cp(state)} vs ${response.state.now.cp}`);
    assert.ok(relativeError(ce(state), response.state.now.ce) < 1e-12, `${name} ce ${ce(state)} vs ${response.state.now.ce}`);
  }
});

test("tciRate(): a plan then pump off touches the target at every interval from 1 to 60 s", () => {
  // The grid fix of R/tci.R: the search runs from dt to dt + tPeak + 10 s.
  const model = resolveModel({ drug: "propofol", weight: 70, height: 170, age: 50, sex: "male" });
  const K = {
    lambda3: model.lambda3, lambda4: model.lambda4, ke0: model.params.ke0, tPeak: model.params.tPeak,
    pbolus: model.coef.pbolus, pinf: model.coef.pinf, ebolus: model.coef.ebolus, einf: model.coef.einf, coef: model.coef,
  };
  for (const seconds of [1, 5, 10, 30, 60]) {
    const dt = seconds / 60;
    const x = tciRate([0, 0, 0], [0, 0, 0, 0], 3, "effect", dt, K);
    assert.ok(x.effectMode);
    let state = advance(emptyState(), dt, x.rate, model);
    let peak = 0;
    for (let s = 0; s <= (K.tPeak + 1) * 60; s++) {
      peak = Math.max(peak, ce(advance(state, s / 60, 0, model)));
    }
    assert.ok(peak <= 3 * (1 + 1e-9), `${seconds} s: peak ${peak}`);
    assert.ok(peak >= 3 * (1 - 1e-4), `${seconds} s: peak ${peak} short of the target`);
  }
  assert.deepEqual(tciRate([0, 0, 0], [0, 0, 0, 0], 0, "effect", 1 / 6, K), { rate: 0, effectMode: false });
});

test("a plasma target is held exactly at the end of the interval", () => {
  const r = baseRequest();
  r.target.site = "plasma";
  r.pump = { rateUnits: "mg/min", maxRate: 1e5 };
  delete r.infusate;
  const response = tciNextRate(r, receivedAtFor(r));
  assert.equal(response.controller.plan, "plasma");
  assert.equal(response.controller.phase, "loading");
  assert.ok(Math.abs(response.state.holdUntil.cp - 3) < 1e-9);
  assert.equal(response.prediction.onTarget, true);
  assert.equal(response.prediction.targetReachedAt, response.timing.holdUntil);
});

test("the pump's limits in order: maxRate, minRate, rateResolution, never rounding up", () => {
  let r = baseRequest();
  r.pump = { rateUnits: "mL/hr", maxRate: 999.9, rateResolution: 0.1 };
  let response = tciNextRate(r, receivedAtFor(r));
  assert.equal(response.rate.value, 999.9); // the ceiling IS a multiple: not pulled back a step
  assert.deepEqual(response.rate.limitedBy, ["maxRate"]);
  r = baseRequest();
  r.pump = { rateUnits: "mL/hr", maxRate: 1200, rateResolution: 7 };
  response = tciNextRate(r, receivedAtFor(r));
  assert.equal(response.rate.value, 1197);
  assert.deepEqual(response.rate.limitedBy, ["maxRate", "rateResolution"]);
  r = baseRequest();
  r.pump = { rateUnits: "mL/hr", maxRate: 5000, minRate: 2000 };
  response = tciNextRate(r, receivedAtFor(r));
  assert.equal(response.rate.value, 0);
  assert.deepEqual(response.rate.limitedBy, ["minRate"]);
  assert.equal(response.controller.phase, "waitingForPeak");
  assert.equal(response.timing.nextRequestAt, "2026-10-11T14:00:10.000Z"); // a floor's zero keeps the usual time
});

test("every number a pump acts on is finite in every fixture response", () => {
  const walk = (x, path) => {
    if (Array.isArray(x)) x.forEach((v, i) => walk(v, `${path}/${i}`));
    else if (x && typeof x === "object") for (const k of Object.keys(x)) walk(x[k], `${path}/${k}`);
    else if (typeof x === "number") assert.ok(Number.isFinite(x), path);
  };
  for (const c of rateCases.cases) {
    const r = tciNextRate(c.request, receivedAtFor(c.request));
    for (const key of ["rate", "segment", "fallback", "state", "prediction", "delivered"]) walk(r[key], `/${key}`);
  }
});

